def ordered(p):
 g=len(p)
 return [[sum(p[i+1][a]*p[i][b] for i in range(g-1))/max(g-1,1) for b in range(4)] for a in range(4)]

def null_pair_sum(p):
 g=len(p)
 return [[sum(p[i][a]*p[j][b] for i in range(g) for j in range(g) if i"'!=j)/max(g*(g-1),1) for b in range(4)] for a in range(4)]

def null_formula(p):
 g=len(p);s=[sum(q[a] for q in p) for a in range(4)]
 return [[max(s[a]*s[b]-sum(q[a]*q[b] for q in p),0)/max(g,1)/max(g-1,1) if g>1 else 0. for b in range(4)] for a in range(4)]

def marg(m):
 c=[[sum(m[2*a+b][2*z+w] for b in range(2) for w in range(2)) for z in range(2)] for a in range(2)]
 b=[[sum(m[2*a+x][2*z+y] for a in range(2) for z in range(2)) for y in range(2)] for x in range(2)]
 return c,b

def product(m):
 c,b=marg(m)
 return [[c[a//2][z//2]*b[a%2][z%2] for z in range(4)] for a in range(4)]

